mapper.select:
select c.*,o.orgname as linkOrgName,r.orgname as linkDeptName,s.realname as createname from TBL_RISKMONITORING_CREATION c left join tbl_organization o on o.orgid=c.linkorgid left join tbl_organization r on r.orgid=c.linkdeptid left join tbl_staff s on s.staffid=c.createstaffid where 1=1
and riskyear LIKE concat(concat('%',#{param.riskyear}),'%')
and quartername LIKE concat(concat('%',#{param.quartername}),'%')
and createstaffid =#{param.createstaffid}
and linkOrgId =#{param.linkOrgId}
${sql}
order by createtime desc
